INSERT INTO "revisions" VALUES('8ac39f2d9171a414d99d4b6f19efa57967b766b0f275d785ce0bd1b98c482f17','bounds_legacy','{"entry":"main.nex","files":{"main.nex":"module bounds_legacy; struct Box<T> {value:T;} fn identity<T>(x:T) -> T {return x;} fn main() -> unit !{io} {let b:Box<i64> = Box(identity(42));print(b.value);} test fn example() -> unit {assert(identity(42) == 42);}"},"schema":"nex.sources/1"}','/private/var/folders/hg/b7ggtzxs1pd_5jwc99gprqwh0000gq/T/nex-07-fixture-jsj46nt_/main.nex','2026-10-17T15:10:49.177Z','0.7');
